using System;
using System.Collections.Generic;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.UI;
using TMPro;

namespace BitSorter.View
{
    /// <summary>
    /// The front door: a title, where you left off, and the way back to it.
    /// </summary>
    /// <remarks>
    /// An overlay in the same scene rather than a separate one, for the same reason level select is:
    /// the play scene is generated by the scene builder, so a second scene would be a second thing to
    /// construct and keep in step, and the session already switches level at runtime.
    ///
    /// Shown at startup. Until something is chosen the board is covered, and <see cref="UiModal"/>
    /// keeps the keyboard quiet as well -- otherwise Q behind the menu would change level under it.
    /// </remarks>
    public sealed class MainMenu : FullScreenPanel
    {
        [SerializeField] private LevelSession _session;
        [SerializeField] private ProgressTracker _progress;
        [SerializeField] private LevelSelectPanel _levels;
        [SerializeField] private SandboxPanel _sandbox;
        [SerializeField] private SettingsPanel _settings;

        [Tooltip("Canvas the menu is built under. Found by type when left empty.")]
        [SerializeField] private Canvas _canvas;

        [Tooltip("Open the menu on startup. Off is useful when working on a level.")]
        [SerializeField] private bool _openOnStart = true;

        private TextMeshProUGUI _progressLine;
        private TextMeshProUGUI _continueLabel;
        private TextMeshProUGUI _nextLine;

        /// <summary>
        /// Held rather than built per call: <see cref="Refresh"/> runs every frame the menu is up, and
        /// a fresh closure each time would be per-frame garbage for a screen that is standing still.
        /// </summary>
        private Predicate<string> _isComplete;

        /// <summary>Whether the menu is covering the board.</summary>
        public bool IsOpen => IsShowing;

        private void Awake()
        {
            if (_session == null) _session = FindFirstObjectByType<LevelSession>();
            if (_progress == null) _progress = FindFirstObjectByType<ProgressTracker>();
            if (_levels == null) _levels = FindFirstObjectByType<LevelSelectPanel>();
            if (_sandbox == null) _sandbox = FindFirstObjectByType<SandboxPanel>();
            if (_settings == null) _settings = FindFirstObjectByType<SettingsPanel>();
            if (_canvas == null) _canvas = FindFirstObjectByType<Canvas>();
        }

        private void Start()
        {
            if (_canvas == null)
                return;

            Build();
            BuildHudButton();
            Show(_openOnStart);
        }

        /// <summary>
        /// The way back to this menu from the board, for the mouse: a quiet button in the top-left
        /// corner, drawn with the rest of the HUD.
        /// </summary>
        /// <remarks>
        /// There was none. A key reached the menu and another the level list, and nothing on screen
        /// was a button to either, so a player who plays with the mouse had no way off a level they did
        /// not want -- free play worst of all, whose setup panel offers only to collapse. The menu is
        /// the front door to everything else, levels and free play included, so one button here is
        /// the way out of every board.
        ///
        /// Top left, because it is the one corner nothing else uses: the banner is centred, the
        /// parts list hangs from the left edge's middle, and the right is the meter, the badge and
        /// the panels.
        /// </remarks>
        private void BuildHudButton()
        {
            Button button = UiTheme.Button_(
                HudButtonName, _canvas.transform, "MENU", out TextMeshProUGUI _, UiType.Label, ButtonRole.Quiet);

            _hudButton = button.GetComponent<RectTransform>();
            UiTheme.Anchor(_hudButton, new Vector2(0f, 1f), new Vector2(0f, 1f),
                new Vector2(UiTheme.Margin, -UiTheme.Margin), new Vector2(HudButtonWidth, UiTheme.ButtonHeight));

            button.onClick.AddListener(() => { Show(true); UiTheme.Defocus(); });
        }

        /// <summary>The HUD's menu button's object name, which the HUD tests look for.</summary>
        public const string HudButtonName = "Menu button";

        private const float HudButtonWidth = 110f;

        private RectTransform _hudButton;

        private void Update()
        {
            Keyboard keyboard = Keyboard.current;

            // Escape: it closes whatever is on top, and with nothing on top it is the way here -- the
            // pause-menu key players reach for first. It was M, and Escape opened the level list;
            // swapped after a playtest, 2026-09-26.
            //
            // Opens only when nothing else is open or has just closed, so the Escape that closes a
            // panel does not open this behind it -- M behind the level list once stacked the menu
            // under it, two full-screen panels at once, one of them unreachable. Nor while the
            // solved card or a hint is up: each is on top and takes Escape itself, and neither is a
            // modal, so each says so. And not on the frame this opened: the Escape that leaves
            // Settings opens this in the same frame, and must not close it again.
            if (keyboard != null && keyboard.escapeKey.wasPressedThisFrame && !OpenedThisFrame)
            {
                if (IsShowing)
                    Show(false);
                else if (!UiModal.OpenOrJustClosed && !WinPanel.HoldsEscape && !HintBanner.HoldsEscape)
                    Show(true);
            }

            // Part of the HUD, so it steps aside for any full-screen panel -- this menu included.
            if (_hudButton != null)
                UiTheme.SetShown(_hudButton, UiModal.HudVisible);

            if (IsShowing)
                Refresh();
        }

        // -----------------------------------------------------------------
        // Building
        // -----------------------------------------------------------------

        /// <summary>Where the button column starts, and how far apart its rows are.</summary>
        /// <remarks>
        /// The step is the row height plus the gap, which is what makes the column read as one
        /// list rather than as buttons that happen to be near each other.
        /// </remarks>
        private const float FirstRow = 32f;

        /// <inheritdoc cref="FirstRow"/>
        private const float RowStep = 54f;

        /// <summary>How the two lines under the column sit against the row that would follow it.</summary>
        private const float NextLineLead = 6f;

        /// <inheritdoc cref="NextLineLead"/>
        private const float ProgressLineStep = 26f;

        private void Build()
        {
            Image scrim = UiTheme.Scrim("Main menu", _canvas.transform, Palette.Current.MenuScrim);
            Root = scrim.GetComponent<RectTransform>();
            UiTheme.Stretch(Root);

            TextMeshProUGUI title = UiTheme.Label(
                "title", Root, UiType.Display, UiTheme.Accent, TextAlignmentOptions.Center);
            UiTheme.Anchor(title.rectTransform, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f),
                new Vector2(0f, 150f + Lift), new Vector2(700f, 70f));
            title.text = "BITSORTER";

            TextMeshProUGUI tagline = UiTheme.Label(
                "tagline", Root, UiType.Body, UiTheme.TextDim, TextAlignmentOptions.Center);
            UiTheme.Anchor(tagline.rectTransform, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f),
                new Vector2(0f, 104f + Lift), new Vector2(700f, 26f));
            tagline.text = "bits fall through logic. sort them.";

            // A rule under the title. The menu was a title and three buttons floating in black,
            // which reads as unfinished rather than as spare.
            Image rule = UiTheme.Panel_("rule", Root, Palette.Current.Rule);
            rule.sprite = null;   // two pixels tall: shorter than the panel's corners, so a plain hairline
            UiTheme.Anchor(rule.GetComponent<RectTransform>(),
                new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f),
                new Vector2(0f, 78f + Lift), new Vector2(320f, 2f));

            // A cursor down the column rather than a y per row. One row is compiled out in a
            // browser build, and with each row stating its own position the two lines underneath
            // stayed where they were -- leaving a button-shaped hole in the middle of the menu
            // that only ever appeared in the shipped web build.
            float row = FirstRow;

            Button resume = Item("Continue", row, out _continueLabel, ButtonRole.Primary);
            resume.onClick.AddListener(() => Fire(Continue));
            row -= RowStep;

            Button levels = Item("Levels", row, out TextMeshProUGUI _);
            levels.onClick.AddListener(() => Fire(OpenLevels));
            row -= RowStep;

            // Below the run, not beside it. Free play is where someone goes once the levels have
            // taught them something, and putting it first would offer a blank board to a player who
            // has not yet been told what a board is for.
            Button sandbox = Item("Sandbox", row, out TextMeshProUGUI _);
            sandbox.onClick.AddListener(() => Fire(OpenSandbox));
            row -= RowStep;

            // Sound and the off switch for reporting live here, one click down, beside starting
            // over. They were rows of this menu, which could say ON or OFF and nothing else -- the
            // data switch never said what it switched. The README tells players where it is.
            Button settings = Item("Settings", row, out TextMeshProUGUI _);
            settings.onClick.AddListener(() => Fire(OpenSettings));
            row -= RowStep;

            // No Quit in a browser. Application.Quit does nothing there -- a tab is closed by the
            // browser, not by the page -- so the button would sit in the menu doing nothing at all,
            // which is worse than not offering it.
#if !UNITY_WEBGL || UNITY_EDITOR
            Button quit = Item("Quit", row, out TextMeshProUGUI _);
            quit.onClick.AddListener(() => Fire(Quit));
            row -= RowStep;
#endif

            // Where Continue actually goes. "CONTINUE" alone tells a returning player nothing about
            // which of nine levels they are about to land on.
            //
            // Measured from wherever the column actually ended, so the pair closes up behind a row
            // that was not built rather than hanging below the gap it left.
            _nextLine = UiTheme.Label(
                "next", Root, UiType.Label, UiTheme.Accent, TextAlignmentOptions.Center);
            UiTheme.Anchor(_nextLine.rectTransform, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f),
                new Vector2(0f, row + NextLineLead + Lift), new Vector2(700f, 22f));

            _progressLine = UiTheme.Label(
                "progress", Root, UiType.Label, UiTheme.TextDim, TextAlignmentOptions.Center);
            UiTheme.Anchor(_progressLine.rectTransform, new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f),
                new Vector2(0f, row + NextLineLead - ProgressLineStep + Lift), new Vector2(700f, 24f));

            TextMeshProUGUI keys = UiTheme.Label(
                "keys", Root, UiType.Caption, UiTheme.TextDim, TextAlignmentOptions.Center);
            UiTheme.Anchor(keys.rectTransform, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f),
                new Vector2(0f, 30f), new Vector2(900f, 20f));
            // From ControlsReference, not spelled out here. This was a literal, which made it a
            // second hand-written copy of the bindings -- and the only place in the whole game that
            // mentioned M, so the tutorial's card never taught the way back to this screen.
            keys.text = ControlsReference.MenuLine;

            // The menu's music is two imported tracks, and one of them is CC BY: its licence asks
            // for the credit wherever the work is used, and this is where it is heard.
            TextMeshProUGUI credit = UiTheme.Label(
                "music credit", Root, UiType.Micro, Palette.Current.Credit, TextAlignmentOptions.Center);
            UiTheme.Anchor(credit.rectTransform, new Vector2(0.5f, 0f), new Vector2(0.5f, 0f),
                new Vector2(0f, 10f), new Vector2(1100f, 16f));
            credit.text = GameAudio.MenuMusicCredit;

            // Which build this is, in the corner, as small as the credit: someone reporting a bug
            // should be able to say which version they saw it in. Read from the build rather than
            // written here, so it cannot say one version while being another.
            TextMeshProUGUI version = UiTheme.Label(
                "version", Root, UiType.Micro, Palette.Current.Credit, TextAlignmentOptions.Right);
            UiTheme.Anchor(version.rectTransform, new Vector2(1f, 0f), new Vector2(1f, 0f),
                new Vector2(-UiTheme.Margin, 10f), new Vector2(120f, 16f));
            version.text = VersionText;
        }

        /// <summary>The version the corner of the menu shows: the build's own, as "v3.0.0".</summary>
        public static string VersionText => "v" + Application.version;

        /// <summary>
        /// How far the whole menu block sits above the middle of the screen.
        /// </summary>
        /// <remarks>
        /// The block runs from the title's top to the bottom of the progress line, and it grew
        /// downward twice -- once for Sandbox, once for Data -- while the title stayed where it
        /// was. That put its middle about seventy units below the screen's, which reads as the menu
        /// hanging low rather than as anything being wrong. Sound and Data then became one Settings
        /// row, which took a row's height off the block and half of it off this.
        ///
        /// One number added to every row, rather than each row's offset nudged separately: the rows
        /// are stated relative to each other on purpose, and re-typing eleven of them is how that
        /// stops being true. The keys line at the bottom is anchored to the screen's edge instead
        /// and is not part of the block.
        /// </remarks>
        private const float Lift = 43f;

        private Button Item(string name, float y, out TextMeshProUGUI label,
            ButtonRole role = ButtonRole.Secondary)
        {
            Button button = UiTheme.Button_(name, Root, name.ToUpperInvariant(), out label, role: role);

            UiTheme.Anchor(button.GetComponent<RectTransform>(),
                new Vector2(0.5f, 0.5f), new Vector2(0.5f, 0.5f),
                new Vector2(0f, y + Lift), new Vector2(240f, UiTheme.ButtonHeight + 6f));

            return button;
        }

        // -----------------------------------------------------------------
        // Contents
        // -----------------------------------------------------------------

        private void Refresh()
        {
            if (_session == null || !_session.IsLoaded)
                return;

            int total = _session.Catalogue.Count;
            int done = SolvedCount();

            _progressLine.text = MenuRules.DescribeProgress(done, total);

            // "Continue" on a fresh save is a lie -- there is nothing to continue from.
            bool fresh = done == 0 && _session.LevelIndex == 0;

            _continueLabel.text = fresh ? "START" : "CONTINUE";

            // Named from the same walk Continue itself uses, so the label cannot promise one level
            // and the button open another. Asked only once the run is known to have a frontier left:
            // an empty catalogue has no next level, and used to throw here rather than say so.
            if (MenuRules.AllSolved(done, total))
                _nextLine.text = "all solved -- replay anything you like";
            else if (TryNextUp(out LevelEntry next))
                _nextLine.text = $"next up: {next.DisplayName}";
            else
                _nextLine.text = string.Empty;
        }

        /// <summary>The level <see cref="Continue"/> would open, if the run has one.</summary>
        private bool TryNextUp(out LevelEntry next) =>
            MenuRules.TryNextUp(_session.Catalogue, IsComplete, out next);

        private Predicate<string> IsComplete =>
            _isComplete ?? (_isComplete = name => _progress != null && _progress.IsComplete(name));

        // The same predicate Continue walks with, so the count and the frontier can never disagree
        // about what is solved.
        private int SolvedCount() => MenuRules.SolvedCount(_session.Catalogue, IsComplete);

        // -----------------------------------------------------------------
        // Choices
        // -----------------------------------------------------------------

        /// <summary>
        /// Closes the menu onto the first level not yet solved.
        /// </summary>
        /// <remarks>
        /// Furthest unsolved rather than last played, because the two differ exactly when it matters:
        /// a player who wandered into a late level from the list and closed the game should come back
        /// to the run, not to wherever they were browsing. Everything solved means the last level, so
        /// the button always goes somewhere.
        /// </remarks>
        private void Continue()
        {
            if (_session == null || !_session.IsLoaded)
                return;

            // The empty-catalogue guard lives in the walk now, so both callers get it.
            if (!TryNextUp(out LevelEntry next))
                return;

            // Closed only once there is somewhere to close onto. The other order dismissed the
            // menu and then discovered it had nowhere to go, leaving a broken install showing a
            // board with no level on it and nothing on screen saying why.
            Show(false);

            if (next.FileName != _session.LevelName)
                _session.LoadLevel(next.FileName);
        }

        /// <inheritdoc cref="Continue"/>
        private void OpenLevels()
        {
            if (_levels == null)
                return;

            Show(false);
            _levels.Open();
        }

        /// <inheritdoc cref="Continue"/>
        private void OpenSandbox()
        {
            if (_sandbox == null)
                return;

            Show(false);
            _sandbox.Open();
        }

        /// <inheritdoc cref="Continue"/>
        private void OpenSettings()
        {
            if (_settings == null)
                return;

            Show(false);
            _settings.Open();
        }

#if !UNITY_WEBGL || UNITY_EDITOR
        private static void Quit()
        {
#if UNITY_EDITOR
            // Application.Quit does nothing in the editor, so a Quit button that appeared to be
            // broken is worse than one that leaves play mode.
            UnityEditor.EditorApplication.isPlaying = false;
#else
            Application.Quit();
#endif
        }
#endif

        // -----------------------------------------------------------------
        // Showing
        // -----------------------------------------------------------------

        public void Show(bool visible) => SetShowing(visible);

        protected override void OnShown() => Refresh();

        private void Fire(System.Action action)
        {
            action();
            UiTheme.Defocus();
        }
    }
}
